# -------------------------
# DATA PARSING
# -------------------------

def _clean_csv(text: str) -> str:
    return text.strip().replace("\\", "")


def parse_eskf(text: str):
    reader = csv.DictReader(io.StringIO(_clean_csv(text)))

    t, pos, vel = [], [], []

    for row in reader:
        t.append(float(row["time_s"]))
        pos.append([
            float(row["rov_pos_n"]),
            float(row["rov_pos_e"]),
            float(row["rov_pos_d"]),
        ])
        vel.append([
            float(row["rov_vel_n"]),
            float(row["rov_vel_e"]),
            float(row["rov_vel_d"]),
        ])

    return np.array(t), np.array(pos), np.array(vel)


def load_rov_gt_csv(path: Path):
    import pandas as pd

    df = pd.read_csv(path)

    t = df["t_sim_sec"].to_numpy()

    pos = df[["x_n", "y_e", "z_d"]].to_numpy()
    vel = df[["vx_n", "vy_e", "vz_d"]].to_numpy()

    return t, pos, vel

def parse_fgo(text: str):
    reader = csv.DictReader(io.StringIO(_clean_csv(text)))

    buckets = {}
    t0 = None  # reference time

    for row in reader:
        raw_t = float(row["time"])

        # Normalize to t = 0
        if t0 is None:
            t0 = raw_t

        # t = raw_t - t0  # <-- THIS FIXES EVERYTHING
        t = round(raw_t - t0, 3)   # <-- THIS FIX

        pos = np.array([float(row["x"]), float(row["y"]), float(row["z"])])
        vel = np.array([float(row["vx"]), float(row["vy"]), float(row["vz"])])

        if t not in buckets:
            buckets[t] = {"pos": [], "vel": []}

        buckets[t]["pos"].append(pos)
        buckets[t]["vel"].append(vel)

    times = sorted(buckets.keys())

    pos_mean = []
    vel_mean = []

    for t in times:
        pos_mean.append(np.mean(buckets[t]["pos"], axis=0))
        vel_mean.append(np.mean(buckets[t]["vel"], axis=0))

    return np.array(times), np.array(pos_mean), np.array(vel_mean)



# -------------------------
# RMSE COMPUTATION
# -------------------------

def compute_rmse(est, gt):
    err = est - gt
    return np.linalg.norm(err, axis=1)


def interpolate_gt(gt_time, gt_vals, query_time):
    return np.vstack([
        np.interp(query_time, gt_time, gt_vals[:, i])
        for i in range(gt_vals.shape[1])
    ]).T

def tseq_to_numpy(tseq):
    t = np.array([ti for ti, _ in tseq])
    pos = np.array([state.pos for _, state in tseq])
    vel = np.array([state.vel for _, state in tseq])
    return t, pos, vel


# -------------------------
# PLOTTING
# -------------------------

def plot_rmse(time, pos_rmse, vel_rmse, label):
    fig, axes = plt.subplots(2, 1, figsize=(7.5, 7.5), sharex=True)

    # Position RMSE
    axes[0].plot(time, pos_rmse, label=f"{label} pos RMSE")
    axes[0].set_ylabel("RMSE [m]")
    axes[0].set_title("ROV Position RMSE")
    axes[0].grid(True, linestyle="--", alpha=0.4)
    axes[0].legend()

    # Velocity RMSE
    axes[1].plot(time, vel_rmse, label=f"{label} vel RMSE")
    axes[1].set_ylabel("RMSE [m/s]")
    axes[1].set_xlabel("Time [s]")
    axes[1].set_title("ROV Velocity RMSE")
    axes[1].grid(True, linestyle="--", alpha=0.4)
    axes[1].legend()

    fig.suptitle(
        f"{label} RMSE — ROV — [{TRAJECTORY_TYPE.value}]",
        fontsize=14
    )

    fig.tight_layout(rect=[0, 0, 1, 0.94])
    return fig

def plot_rmse_overlay(
    eskf_t, eskf_pos_rmse, eskf_vel_rmse,
    fgo_t,  fgo_pos_rmse,  fgo_vel_rmse,
):
    fig, axes = plt.subplots(2, 1, figsize=(7.5, 7.5), sharex=True)

    # ---- POSITION ----
    axes[0].plot(
        eskf_t, eskf_pos_rmse,
        label="ESKF",
        # marker="o",
        markevery=max(len(eskf_t)//20, 1)
    )
    axes[0].plot(
        fgo_t, fgo_pos_rmse,
        label="FGO",
        # marker="s",
        markevery=max(len(fgo_t)//20, 1)
    )

    axes[0].set_ylabel("RMSE [m]")
    axes[0].set_title("ROV Position RMSE")
    axes[0].grid(True, linestyle="--", alpha=0.4)


    # ---- VELOCITY ----
    axes[1].plot(
        eskf_t, eskf_vel_rmse,
        label="ESKF",
        # marker="o",
        markevery=max(len(eskf_t)//20, 1)
    )
    axes[1].plot(
        fgo_t, fgo_vel_rmse,
        label="FGO",
        # marker="s",
        markevery=max(len(fgo_t)//20, 1)
    )

    axes[1].set_ylabel("RMSE [m/s]")
    axes[1].set_xlabel("Time [s]")
    axes[1].set_title("ROV Velocity RMSE")
    axes[1].grid(True, linestyle="--", alpha=0.4)


    # ---- Legend (only bottom, like exp1 style) ----
    axes[1].legend(loc="upper right", fontsize=9)

    # ---- Title ----
    title = FIGURE_8_NAME if TRAJECTORY_TYPE == TrajectoryType.FIGURE_8 else LINEAR_TURNS_NAME
    fig.suptitle(
        rf"{title}: RMSE vs time",
        fontsize=14
    )

    fig.tight_layout(rect=[0, 0, 1, 0.94])
    return fig

# -------------------------
# MAIN
# -------------------------

def main():
    print("Parsing arguments...")
    parser = argparse.ArgumentParser(description="Plot RMSE over time.")
    parser.add_argument("--output-dir", type=Path, default=f"results/{TRAJECTORY_TYPE.value}",)
    parser.add_argument("--no-show", action="store_true")
    args = parser.parse_args()

    # ---- Parse your data strings ----
    eskf_t, eskf_pos, eskf_vel = parse_eskf(eskf_data)
    fgo_t, fgo_pos, fgo_vel = parse_fgo(fgo_data)

    # ---- Generate GT ----
    gt_path = FIG_8_GT_PATH if TRAJECTORY_TYPE == TrajectoryType.FIGURE_8 else LINEAR_TURNS_GT_PATH

    t_gt, rov_gt_pos, rov_gt_vel = load_rov_gt_csv(gt_path)

    # ---- Align GT ----
    eskf_gt_pos = interpolate_gt(t_gt, rov_gt_pos, eskf_t)
    eskf_gt_vel = interpolate_gt(t_gt, rov_gt_vel, eskf_t)

    fgo_gt_pos = interpolate_gt(t_gt, rov_gt_pos, fgo_t)
    fgo_gt_vel = interpolate_gt(t_gt, rov_gt_vel, fgo_t)

    # ---- Compute RMSE ----
    eskf_rmse_pos = compute_rmse(eskf_pos, eskf_gt_pos)
    eskf_rmse_vel = compute_rmse(eskf_vel, eskf_gt_vel)

    fgo_rmse_pos = compute_rmse(fgo_pos, fgo_gt_pos)
    fgo_rmse_vel = compute_rmse(fgo_vel, fgo_gt_vel)

    # ---- Plot ----
    fig_eskf = plot_rmse(eskf_t, eskf_rmse_pos, eskf_rmse_vel, "ESKF")
    fig_fgo = plot_rmse(fgo_t, fgo_rmse_pos, fgo_rmse_vel, "FGO")

    overlay_fig = plot_rmse_overlay(
        eskf_t, eskf_rmse_pos, eskf_rmse_vel,
        fgo_t,  fgo_rmse_pos,  fgo_rmse_vel,
    )

    print("GT time range:", t_gt[0], t_gt[-1])
    print("ESKF time range:", eskf_t[0], eskf_t[-1])
    print("FGO time range:", fgo_t[0], fgo_t[-1])

    # ---- Save ----
    if args.output_dir:
        args.output_dir.mkdir(parents=True, exist_ok=True)
        # fig_eskf.savefig(args.output_dir / "eskf_rmse.svg", bbox_inches="tight")
        # fig_fgo.savefig(args.output_dir / "fgo_rmse.svg", bbox_inches="tight")
        overlay_fig.savefig(args.output_dir / "rmse_overlay.svg", bbox_inches="tight")

    if not args.no_show:
        plt.show()

